+<body>
+  <main class="quiz-shell">
+    <h1>Computer Languages Quiz</h1>
+    <p class="intro">Pick all answers that apply for each question, then submit to see how you did.</p>
+
+    <form id="quiz-form">
+      <div class="form-field">
+        <fieldset>
+          <legend>1. Which of these are programming languages commonly used for web development?</legend>
+          <p class="help-text">Select every answer you believe is correct. More than one option applies.</p>
+          <div class="choices">
+            <label class="choice"><input type="checkbox" name="q1" value="JavaScript">JavaScript</label>
+            <label class="choice"><input type="checkbox" name="q1" value="Python">Python</label>
+            <label class="choice"><input type="checkbox" name="q1" value="HTML">HTML</label>
+            <label class="choice"><input type="checkbox" name="q1" value="Ruby">Ruby</label>
+          </div>
+        </fieldset>
+      </div>
+
+      <div class="form-field">
+        <fieldset>
+          <legend>2. Which of these languages are primarily used for styling or describing markup rather than general-purpose programming?</legend>
+          <div class="choices">
+            <label class="choice"><input type="checkbox" name="q2" value="CSS">CSS</label>
+            <label class="choice"><input type="checkbox" name="q2" value="HTML">HTML</label>
+            <label class="choice"><input type="checkbox" name="q2" value="Java">Java</label>
+            <label class="choice"><input type="checkbox" name="q2" value="C++">C++</label>
