      transform: translateY(-1px);
      border-color: rgba(96, 165, 250, 0.55);
      background: rgba(37, 99, 235, 0.14);
    }

    input[type="checkbox"] {
      width: 18px;
      height: 18px;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
      margin-top: 4px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: white;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.15s ease, box-shadow 0.15s ease;
      box-shadow: 0 12px 28px rgba(59, 130, 246, 0.35);
    }

    button:hover,
    button:focus-visible {
      transform: translateY(-1px);
      box-shadow: 0 14px 32px rgba(59, 130, 246, 0.45);
    }

    #result {
      min-height: 1.5rem;
      color: var(--muted);
      font-weight: 600;
    }

    .success {
      color: var(--success);
    }

    .warning {
      color: #fbbf24;
    }

    .danger {
      color: var(--danger);
    }
  </style>
</head>
<body>
  <main class="quiz-shell">
    <h1>Computer Languages Quiz</h1>
    <p class="intro">Pick all answers that apply for each question, then submit to see how you did.</p>

