            <label class="choice"><input type="checkbox" name="q1" value="Ruby">Ruby</label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which of these languages are primarily used for styling or describing markup rather than general-purpose programming?</legend>
          <div class="choices">
            <label class="choice"><input type="checkbox" name="q2" value="CSS">CSS</label>
            <label class="choice"><input type="checkbox" name="q2" value="HTML">HTML</label>
            <label class="choice"><input type="checkbox" name="q2" value="Java">Java</label>
            <label class="choice"><input type="checkbox" name="q2" value="C++">C++</label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which languages are often associated with systems programming?</legend>
          <div class="choices">
            <label class="choice"><input type="checkbox" name="q3" value="C">C</label>
            <label class="choice"><input type="checkbox" name="q3" value="Rust">Rust</label>
            <label class="choice"><input type="checkbox" name="q3" value="TypeScript">TypeScript</label>
            <label class="choice"><input type="checkbox" name="q3" value="Go">Go</label>
          </div>
        </fieldset>
      </div>

      <div class="actions">
        <button type="submit">Submit Quiz</button>
        <output id="result" aria-live="polite"></output>
      </div>
    </form>
  </main>

  <script>
    const quizForm = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    const answerKey = {
      q1: ['JavaScript', 'Python', 'Ruby'],
      q2: ['CSS', 'HTML'],
      q3: ['C', 'Rust', 'Go']
    };

    function getSelectedValues(questionName) {
      return Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`))
        .map((input) => input.value)
        .sort();
    }

    function arraysMatch(a, b) {
      return a.length === b.length && a.every((value, index) => value === b[index]);
    }

    quizForm.addEventListener('submit', function (event) {
      event.preventDefault();

      let score = 0;
