      Object.keys(answerKey).forEach((questionName) => {
        const selected = getSelectedValues(questionName);
        const correct = [...answerKey[questionName]].sort();

        if (selected.length === 0) {
          unanswered += 1;
        }

        if (arraysMatch(selected, correct)) {
          score += 1;
        }
      });

      result.className = '';

