        result.classList.add('warning');
        result.textContent = `You scored ${score} out of 3. ${unanswered} question${unanswered === 1 ? '' : 's'} still had no selections.`;
        return;
      }

      result.classList.add(score === 3 ? 'success' : 'danger');
      result.textContent = score === 3
        ? 'Perfect score: 3 out of 3.'
        : `You scored ${score} out of 3.`;
    });
  </script>
